def can_transform(n, m, a, k, b):
    i = 0
    j = 0

    while j < k:
        found = False
        while i < n:
            if a[i] % m == 0 and a[i] // m == b[j]:
                a[i] = 0  # Mark as used
                i += 1
                j += 1
                found = True
                break
            elif a[i] != 0:
                count = 0
                temp_i = i
                while temp_i < n and count < m and a[temp_i] % m == 0 and a[temp_i] // m == b[j]:
                    count += 1
                    temp_i += 1
                if count == m:
                    i = temp_i
                    j += 1
                    found = True
                    break
            i += 1
        if not found:
            return "No"
    return "Yes"

def main():
    t = int(input())
    results = []

    for _ in range(t):
        n, m = map(int, input().split())
        a = list(map(int, input().split()))
        k = int(input())
        b = list(map(int, input().split()))

        results.append(can_transform(n, m, a, k, b))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
